from common import *
from urllib.parse import quote
plan=read(HERE/'plan.json');rows={e['id']:dict(file=e['id']+'/'+quote(Path(next(f['path'] for f in e['baselineFiles'] if f['kind']=='captioned.mp4')).name),title=e['title']) for e in plan['episodes']}
data=json.dumps(rows,ensure_ascii=False).replace('</','<\\/')
page="""<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Encoded motion inspection</title><style>body{margin:0;background:#080c0a;color:#f3f5ef;font:16px system-ui}main{max-width:1280px;margin:auto;padding:12px}video{width:100%;aspect-ratio:16/9;background:black}input,select,button{font:inherit;padding:8px;background:#17231c;color:inherit;border:1px solid #425247}h1{font-size:22px;color:#f2d787}p{margin:8px 0}</style><main><h1 id="title"></h1><video id="movie" controls playsinline muted preload="metadata"></video><p><select id="episode"></select> <input id="seconds" type="number" aria-label="재생 시각" step="0.1" value="0"> <button id="seek">구간 보기</button> <button id="pause">정지</button></p><p id="status"></p></main><script>const rows=DATA;const el=id=>document.getElementById(id);const params=new URLSearchParams(location.search);for(const key of Object.keys(rows)){const option=document.createElement('option');option.textContent=key;el('episode').append(option)}el('episode').value=rows[params.get('ep')]?params.get('ep'):'A03';el('seconds').value=params.get('t')||0;function choose(){const ep=el('episode').value;el('title').textContent=ep+' '+rows[ep].title;el('movie').src=rows[ep].file}el('episode').onchange=choose;el('movie').onloadedmetadata=()=>{el('movie').currentTime=Number(el('seconds').value)};el('seek').onclick=()=>{el('movie').currentTime=Number(el('seconds').value);el('movie').play()};el('pause').onclick=()=>el('movie').pause();el('movie').ontimeupdate=()=>el('status').textContent=el('movie').currentTime.toFixed(2)+' / '+el('movie').duration.toFixed(2)+' seconds';choose();</script></html>""".replace('DATA',data)
(OUTPUT/'inspection.html').write_text(page,encoding='utf-8')
print(OUTPUT/'inspection.html')
